int fp_is_equal_8x1(__m512i* a, __m512i* b)
{
    __m512i zero[NUM_LIMBS], norm_a[NUM_LIMBS], norm_b[NUM_LIMBS];
    __mmask8 acc;
    fp_setzero_8x1(zero);
    
    // Normalize both to [0, p-1] by adding zero
    fp_add_8x1(norm_a, a, zero);
    fp_add_8x1(norm_b, b, zero);
    
    acc = 0xff;
    acc &= VCMPEQ(norm_a[0], norm_b[0]);
    acc &= VCMPEQ(norm_a[1], norm_b[1]);
    acc &= VCMPEQ(norm_a[2], norm_b[2]);
    acc &= VCMPEQ(norm_a[3], norm_b[3]);
    acc &= VCMPEQ(norm_a[4], norm_b[4]);
    acc &= VCMPEQ(norm_a[5], norm_b[5]);
    acc &= VCMPEQ(norm_a[6], norm_b[6]);
    acc &= VCMPEQ(norm_a[7], norm_b[7]);
    acc &= VCMPEQ(norm_a[8], norm_b[8]);
    acc &= VCMPEQ(norm_a[9], norm_b[9]);
    acc &= VCMPEQ(norm_a[10], norm_b[10]);
    acc &= VCMPEQ(norm_a[11], norm_b[11]);
    acc &= VCMPEQ(norm_a[12], norm_b[12]);
    acc &= VCMPEQ(norm_a[13], norm_b[13]);
    acc &= VCMPEQ(norm_a[14], norm_b[14]);
    acc &= VCMPEQ(norm_a[15], norm_b[15]);
    acc &= VCMPEQ(norm_a[16], norm_b[16]);
    acc &= VCMPEQ(norm_a[17], norm_b[17]);
    acc &= VCMPEQ(norm_a[18], norm_b[18]);
    acc &= VCMPEQ(norm_a[19], norm_b[19]);
    acc &= VCMPEQ(norm_a[20], norm_b[20]);
    acc &= VCMPEQ(norm_a[21], norm_b[21]);
    acc &= VCMPEQ(norm_a[22], norm_b[22]);
    acc &= VCMPEQ(norm_a[23], norm_b[23]);
    acc &= VCMPEQ(norm_a[24], norm_b[24]);
    acc &= VCMPEQ(norm_a[25], norm_b[25]);
    acc &= VCMPEQ(norm_a[26], norm_b[26]);
    acc &= VCMPEQ(norm_a[27], norm_b[27]);
    acc &= VCMPEQ(norm_a[28], norm_b[28]);
    acc &= VCMPEQ(norm_a[29], norm_b[29]);
    acc &= VCMPEQ(norm_a[30], norm_b[30]);
    acc &= VCMPEQ(norm_a[31], norm_b[31]);
    acc &= VCMPEQ(norm_a[32], norm_b[32]);
    acc &= VCMPEQ(norm_a[33], norm_b[33]);
    acc &= VCMPEQ(norm_a[34], norm_b[34]);
    acc &= VCMPEQ(norm_a[35], norm_b[35]);
    acc &= VCMPEQ(norm_a[36], norm_b[36]);
    acc &= VCMPEQ(norm_a[37], norm_b[37]);
    acc &= VCMPEQ(norm_a[38], norm_b[38]);
    acc &= VCMPEQ(norm_a[39], norm_b[39]);
    acc &= VCMPEQ(norm_a[40], norm_b[40]);
    acc &= VCMPEQ(norm_a[41], norm_b[41]);
    acc &= VCMPEQ(norm_a[42], norm_b[42]);
    acc &= VCMPEQ(norm_a[43], norm_b[43]);
    acc &= VCMPEQ(norm_a[44], norm_b[44]);
    acc &= VCMPEQ(norm_a[45], norm_b[45]);
    acc &= VCMPEQ(norm_a[46], norm_b[46]);
    acc &= VCMPEQ(norm_a[47], norm_b[47]);
    acc &= VCMPEQ(norm_a[48], norm_b[48]);
    acc &= VCMPEQ(norm_a[49], norm_b[49]);
    acc &= VCMPEQ(norm_a[50], norm_b[50]);
    acc &= VCMPEQ(norm_a[51], norm_b[51]);
    return acc;
}

