    t[35] = VADD(t[35], VSRA(t[34], LIMB_LEN));
    t[36] = VADD(t[36], VSRA(t[35], LIMB_LEN));
    t[37] = VADD(t[37], VSRA(t[36], LIMB_LEN));
    t[38] = VADD(t[38], VSRA(t[37], LIMB_LEN));
    t[39] = VADD(t[39], VSRA(t[38], LIMB_LEN));
    t[40] = VADD(t[40], VSRA(t[39], LIMB_LEN));
    t[41] = VADD(t[41], VSRA(t[40], LIMB_LEN));
    t[42] = VADD(t[42], VSRA(t[41], LIMB_LEN));
    t[43] = VADD(t[43], VSRA(t[42], LIMB_LEN));
    t[44] = VADD(t[44], VSRA(t[43], LIMB_LEN));
    t[45] = VADD(t[45], VSRA(t[44], LIMB_LEN));
    t[46] = VADD(t[46], VSRA(t[45], LIMB_LEN));
