    t[48] = VADD(t[48], VSRA(t[47], LIMB_LEN));
    t[49] = VADD(t[49], VSRA(t[48], LIMB_LEN));
    t[50] = VADD(t[50], VSRA(t[49], LIMB_LEN));
    t[51] = VADD(t[51], VSRA(t[50], LIMB_LEN));
    t[0] = VAND(t[0], limb_mask);
    t[1] = VAND(t[1], limb_mask);
    t[2] = VAND(t[2], limb_mask);
