    t4 = VMULADDL(t4, a2, b2);
    t5 = VMULADDH(t5, a2, b2);
    t4 = VMULADDL(t4, a3, b1);
    t5 = VMULADDH(t5, a3, b1);
    t4 = VMULADDL(t4, a4, b0);
    t5 = VMULADDH(t5, a4, b0);
    t5 = VSL(t5, LIMB_ALIGN);
    
    t5 = VMULADDL(t5, a0, b5);
