    t[7] = VADDMASK(t[7], 0x55, t[7], VSRA(t[6], LIMB_LEN));
    t[8] = VADDMASK(t[8], 0x55, t[8], VSRA(t[7], LIMB_LEN));
    t[9] = VADDMASK(t[9], 0x55, t[9], VSRA(t[8], LIMB_LEN));
    t[10] = VADDMASK(t[10], 0x55, t[10], VSRA(t[9], LIMB_LEN));
    t[11] = VADDMASK(t[11], 0x55, t[11], VSRA(t[10], LIMB_LEN));
    t[12] = VADDMASK(t[12], 0x55, t[12], VSRA(t[11], LIMB_LEN));
    t[13] = VADDMASK(t[13], 0x55, t[13], VSRA(t[12], LIMB_LEN));
    t[14] = VADDMASK(t[14], 0x55, t[14], VSRA(t[13], LIMB_LEN));
    t[15] = VADDMASK(t[15], 0x55, t[15], VSRA(t[14], LIMB_LEN));
    t[16] = VADDMASK(t[16], 0x55, t[16], VSRA(t[15], LIMB_LEN));
    t[17] = VADDMASK(t[17], 0x55, t[17], VSRA(t[16], LIMB_LEN));
    t[18] = VADDMASK(t[18], 0x55, t[18], VSRA(t[17], LIMB_LEN));
    t[19] = VADDMASK(t[19], 0x55, t[19], VSRA(t[18], LIMB_LEN));
    t[20] = VADDMASK(t[20], 0x55, t[20], VSRA(t[19], LIMB_LEN));
    t[21] = VADDMASK(t[21], 0x55, t[21], VSRA(t[20], LIMB_LEN));
    t[22] = VADDMASK(t[22], 0x55, t[22], VSRA(t[21], LIMB_LEN));
    t[23] = VADDMASK(t[23], 0x55, t[23], VSRA(t[22], LIMB_LEN));
    t[24] = VADDMASK(t[24], 0x55, t[24], VSRA(t[23], LIMB_LEN));
    t[25] = VADDMASK(t[25], 0x55, t[25], VSRA(t[24], LIMB_LEN));
    carry = VSRA(t[25], LIMB_LEN);
    carry = VSHUFFLEMASKZ(0xcccc, carry, 0x4e);
    t[0] = VADDMASK(t[0], 0xaa, t[0], carry);
    t[1] = VADDMASK(t[1], 0xaa, t[1], VSRA(t[0], LIMB_LEN));
    t[2] = VADDMASK(t[2], 0xaa, t[2], VSRA(t[1], LIMB_LEN));
    t[3] = VADDMASK(t[3], 0xaa, t[3], VSRA(t[2], LIMB_LEN));
    t[4] = VADDMASK(t[4], 0xaa, t[4], VSRA(t[3], LIMB_LEN));
    t[5] = VADDMASK(t[5], 0xaa, t[5], VSRA(t[4], LIMB_LEN));
    t[6] = VADDMASK(t[6], 0xaa, t[6], VSRA(t[5], LIMB_LEN));
    t[7] = VADDMASK(t[7], 0xaa, t[7], VSRA(t[6], LIMB_LEN));
    t[8] = VADDMASK(t[8], 0xaa, t[8], VSRA(t[7], LIMB_LEN));
    t[9] = VADDMASK(t[9], 0xaa, t[9], VSRA(t[8], LIMB_LEN));
