    t[24] = VADDMASK(t[24], 0xaa, t[24], VSRA(t[23], LIMB_LEN));
    t[25] = VADDMASK(t[25], 0xaa, t[25], VSRA(t[24], LIMB_LEN));
    t[0] = VAND(t[0], limb_mask);
    t[1] = VAND(t[1], limb_mask);
