    t[19] = VSUB(VADD(a[19], p_bod), b[19]);
    t[20] = VSUB(VADD(a[20], p_bod), b[20]);
    t[21] = VSUB(VADD(a[21], p_bod), b[21]);
    t[22] = VSUB(VADD(a[22], p_bod), b[22]);
    t[23] = VSUB(VADD(a[23], p_bod), b[23]);
    t[24] = VSUB(VADD(a[24], p_bod), b[24]);
    t[25] = VSUB(VADD(a[25], p_top), b[25]);
    
    res[0] = t[0];
    res[1] = t[1];
