    t[8] = VAND(t[8], limb_mask);
    t[9] = VADD(t[9], carry);
    carry = VSRA(t[9], LIMB_LEN);
    t[9] = VAND(t[9], limb_mask);
    t[10] = VADD(t[10], carry);
