    carry = VSRA(t[11], LIMB_LEN);
    t[11] = VAND(t[11], limb_mask);
    t[12] = VADD(t[12], carry);
    carry = VSRA(t[12], LIMB_LEN);
    t[12] = VANDMASK(t[12], 0x77, t[12], limb_mask);
    carry = VPERM512MASKZ(0xee, carry, idx_shift);
    t[0] = VADD(t[0], carry);
    carry = VSRA(t[0], LIMB_LEN);
    t[0] = VAND(t[0], limb_mask);
