    t[5] = VAND(t[5], limb_mask);
    t[6] = VADD(t[6], carry);
    carry = VSRA(t[6], LIMB_LEN);
    t[6] = VAND(t[6], limb_mask);
    t[7] = VADD(t[7], carry);
