    carry = VSRA(t[3], LIMB_LEN);
    t[3] = VAND(t[3], limb_mask);
    t[4] = VADD(t[4], carry);
    carry = VSRA(t[4], LIMB_LEN);
    t[4] = VAND(t[4], limb_mask);
    t[5] = VADD(t[5], carry);
    carry = VSRA(t[5], LIMB_LEN);
    t[5] = VAND(t[5], limb_mask);
    t[6] = VADD(t[6], carry);
    carry = VSRA(t[6], LIMB_LEN);
