    t[40] = (t[40] >> 31) | (t[41] << 33);
    
    // If result is negative, negate it
    uint64_t s = sgnw(t[41]);
    cc = sbb(0, t[0] ^ s, s, &d[0]);
    cc = sbb(cc, t[1] ^ s, s, &d[1]);
    cc = sbb(cc, t[2] ^ s, s, &d[2]);
    cc = sbb(cc, t[3] ^ s, s, &d[3]);
