    umul_add_64(&h[16], &hi, s[16], 1339205162631168ULL, hi);
    umul_add_64(&h[17], &hi, s[17], 1339205162631168ULL, hi);
    umul_add_64(&h[18], &hi, s[18], 1339205162631168ULL, hi);
    umul_add_64(&h[19], &hi, s[19], 1339205162631168ULL, hi);
    umul_add_64(&h[20], &hi, s[20], 1339205162631168ULL, hi);
    umul_add_64(&h[21], &hi, s[21], 1339205162631168ULL, hi);
